import "server-only";
import { neon, Pool, neonConfig } from "@neondatabase/serverless";

if (!process.env.DATABASE_URL) {
  throw new Error("DATABASE_URL is missing from .env.local");
}

/**
 * HTTP mode — tagged template literal for simple, one-shot queries.
 * True serverless: no persistent connection, fully Edge-compatible.
 * Use this for reads and simple writes inside Vercel Functions / Edge routes.
 *
 * Example:
 *   const rows = await sql`SELECT * FROM users WHERE id = ${userId}`;
 */
export const sql = neon(process.env.DATABASE_URL);

/**
 * WebSocket/pool mode — persistent connection within a request.
 * Supports multi-statement transactions; required by @prisma/adapter-neon.
 * In Node.js environments you need a WebSocket constructor (see below);
 * Edge runtimes (Vercel Edge, Cloudflare Workers) have native WebSocket.
 *
 * Example:
 *   const client = await pool.connect();
 *   await client.query("BEGIN");
 *   // ... queries ...
 *   await client.query("COMMIT");
 *   client.release();
 */
export const pool = new Pool({ connectionString: process.env.DATABASE_URL });

