import "server-only";
import { Pool, neonConfig } from "@neondatabase/serverless";
import { PrismaNeon } from "@prisma/adapter-neon";
import { PrismaClient } from "@prisma/client";
import ws from "ws";

// Node.js requires an explicit WebSocket constructor; Edge runtimes have it natively.
neonConfig.webSocketConstructor = ws;

const pool = new Pool({ connectionString: process.env.DATABASE_URL });
const adapter = new PrismaNeon(pool);

// Singleton pattern — prevents creating a new PrismaClient on every hot-reload
// in development. In production each lambda instance has exactly one client.
const globalForPrisma = globalThis as unknown as { prisma: PrismaClient };

export const db =
  globalForPrisma.prisma ?? new PrismaClient({ adapter });

if (process.env.NODE_ENV !== "production") {
  globalForPrisma.prisma = db;
}

import "server-only";
import { drizzle } from "drizzle-orm/neon-http";
import { neon } from "@neondatabase/serverless";

// HTTP driver — no persistent connection, fully Edge-compatible.
// Works on Vercel Functions, Edge Routes, and Cloudflare Workers.
const sql = neon(process.env.DATABASE_URL!);

export const db = drizzle({ client: sql });
