"use server";

import { sql } from "./client";

/**
 * Typed wrapper around the Neon HTTP tagged template literal.
 * Values are automatically parameterized — SQL injection is not possible
 * when using this interface.
 *
 * Example:
 *   const users = await query<User>`SELECT * FROM users WHERE id = ${userId}`;
 */
export async function query<T>(
  strings: TemplateStringsArray,
  ...values: unknown[]
): Promise<T[]> {
  return sql<T[]>(strings, ...values);
}

// Example helper — replace or expand with your own queries.
export async function getRows<T>(table: string): Promise<T[]> {
  // sql.identifier() escapes the table name to prevent injection.
  return sql<T[]>`SELECT * FROM ${sql.identifier(table)} LIMIT 100`;
}
